if(!r.allocation?.overtimePreferred&&Number.isInteger(r.allocation?.overtimeSpread))parts.push('残業の差 '+change(first.allocation?.overtimeSpread??r.allocation.overtimeSpread,r.allocation.overtimeSpread,'回'));
