if(!data.staff.length&&!exists){c.append(el('h2','公休表をつくりましょう'),button('職員を登録する',()=>setTab('staff'),'primary wide'),button('以前のデータを読み込む',()=>$('import').click(),'wide'));view.append(c);return;}
const staff=activeStaff();if(!staff.length){c.append(el('h2','今期に入れる職員がいません'),button('職員を選ぶ',()=>setTab('staff'),'primary wide'));view.append(c);renderWorkingRoster(view);return;}
const meta=metadata(),complete=Object.keys(history()).length===staff.length;
if(state.busy){c.append(el('h2','公休表を作っています'),el('div',undefined,'progress'),el('p',state.progressStage||'人数と夜勤→残業合計→残業回数の公平さ→配置の順に改善します。良くなり続けている間は続け、最大5分ほどで終わります。','muted'),el('p','','muted'));c.lastChild.id='elapsed';view.append(c);return;}
const actions=el('div',undefined,'creation-actions');actions.append(button(AutoRosterUI.active()?'休みも考えて作る':'新しく作る',()=>generate('new'),'primary wide'),el('p','現在の入力条件から作り、残業や偏りまで改善します。必要な追加計算も自動で行います。','muted'));c.append(actions);
c.append(el('p',staffingSummary(),'muted'),button('必要人数を確認・変更',editStaffing,'wide'));
if(!complete)c.append(el('p',`前期の勤務：${Object.keys(history()).length} / ${staff.length}人 入力済み`,'muted'));
c.append(button('前期の勤務を入力',editHistory,'wide'));
if(staff.some(st=>st.type!=='part'&&st.nightShiftType!=='none'))c.append(el('p',nightPreferenceExplanation(),'muted'));
if(state.failure&&state.failure.signature===inputData().signature)c.append(failurePanel(state.failure));
