if(!AutoRosterUI.active()&&!workChanged()&&exists&&!optimal&&(meta?.workflow?.done!==true||meta?.overtimeFairness?.minimumSpreadProven===false)&&(ready()||meta?.status==='DRAFT'))actions.append(button('さらに改善する',()=>generate('improve'),'secondary wide'),el('p','表示中の表を基準に、人数不足や勤務の偏りを減らす配置を探します。','muted'));
else if(!AutoRosterUI.active()&&!workChanged()&&schedule().retryLong===inputData().signature)actions.append(button('別の探し方で計算する',()=>generate('improve'),'secondary wide'));
