function renderWorkingRoster(view){
if(!hasTable())return;
const stale=workChanged(),month=card();month.id='roster-result';month.tabIndex=-1;month.append(el('h2','作業中の公休表'));
if(stale)month.append(el('p','最新の条件とは異なる条件で作成した表です。','muted'));
withWorkingTable(()=>{const meta=metadata();if(meta?.timing&&Number.isFinite(meta.seconds))month.append(el('p',`${meta.timing.mode==='complete'?'作成・改善':meta.timing.mode==='adaptive'?'通常作成':'追加計算'}：${meta.seconds.toFixed(1)}秒`,'muted'));
const checkPanel=stale?null:tableCheckPanel();if(checkPanel)month.append(checkPanel);if(meta?.status==='DRAFT')month.append(shortfallPanel(meta));const exceptionBox=exceptionPanel(meta);if(exceptionBox)month.append(exceptionBox);
month.append(nightPreferencePanel(),allocationSummary(),monthTable(!stale));});
month.append(button('この表を保存',saveTableDialog,'primary wide'),button('印刷する（A4横）',()=>window.print(),'wide'),el('p','この表はこの端末に一時保存されます。条件を編集しても残ります。ずっと残すには「この表を保存」を押してください。','muted'));view.append(month);
const printable=el('div',undefined,'print-only');withWorkingTable(()=>{if(stale)printable.append(el('p','最新の条件とは異なる条件で作成した表です。','legend'));printable.append(monthTable());});view.append(printable);
}

