function abRatioSummary(){const rows=activeStaff().filter(st=>st.type!=='part'&&(st.dayShiftType||'both')==='both').map(st=>Array.from({length:days()},(_,i)=>schedule().assignments[st.id]?.[i+1]));const a=rows.reduce((n,row)=>n+row.filter(k=>k==='early').length,0),b=rows.reduce((n,row)=>n+row.filter(k=>k==='late').length,0),box=el('div');if(a+b){const percent=Math.round(100*a/(a+b));box.append(el('p',`A・B両方できる人の全体比率：A${percent}％・B${100-percent}％`,'muted'));}return box;}
// 残業可能な今期の職員だけを比較し、手直し後も実際の勤務から集計する。
// 出勤できる日数＝期間日数−max(公休の最低日数, 希望休の日数)。計算側（solver/input_data.py）と同じ式。
