const meta=metadata(),proof=[OPTIMIZATION_POLICY,AutoHolidayPolicy.POLICY].includes(meta?.optimizationPolicy)&&meta?.overtimeFairness,map=inputData().map;
const sameTable=proof&&proof.total===total&&Object.keys(proof.byStaff||{}).length===rows.length&&Object.entries(proof.byStaff||{}).every(([id,c])=>rows.find(r=>r.st.id===map[id])?.count===c);
if(!scaled.length&&spread===ideal)box.append(el('p','同じ残業合計では、これ以上均等にできない配分です。','small'));
else if(proof?.minimumSpreadProven&&(sameTable||(!scaled.length&&!proof.byStaff&&proof.spread===spread&&proof.total===total)))box.append(el('p',scaled.length?'出勤できる日数の比率で比べて、人数不足・夜勤などの上位条件と残業合計を維持する範囲で、この配分の差が最少であることを確認しました。':'人数不足・夜勤などの上位条件と残業合計を維持する範囲で、この回数差が最少であることを確認しました。','small'));
else box.append(el('p','この残業回数の差が避けられないかは、まだ確認できていません。','small'));
