// 勤務形態・夜勤の曜日・A残の可否から、その日に入れる勤務（計算側と同じ条件）。
function allowedShifts(st,d){if(st.type==='part')return ['off','part'];const a=['off','nightOff'],w=dateAt(d).getUTCDay();if(st.dayShiftType!=='late')a.push('early');if(st.dayShiftType!=='early')a.push('late');if(st.canOvertime)a.push('overtime');if(st.nightShiftType==='all'||(st.nightShiftType==='weekday'&&w>=1&&w<=4))a.push('night');return a;}
function applyShiftEdit(st,day,shift,fixed){
const s=schedule();s.assignments[st.id]??={};s.locked??={};s.locked[st.id]??={};
const row=s.assignments[st.id],old=row[day];
const put=(date,value)=>{if(date>days())return;row[date]=value;if(fixed)s.locked[st.id][date]=value;else delete s.locked[st.id][date];};
put(day,shift);
if(shift==='night'){put(day+1,'nightOff');put(day+2,'off');}
else if(shift==='nightOff')put(day+1,'off');
else if(old==='night'&&row[day+1]==='nightOff')put(day+1,'off');
}
function editShift(st,day){const d=modal(`${st.name}・${dateLabel(day)}`),s=schedule(),current=s.assignments[st.id]?.[day]||'off',ok=allowedShifts(st,day),sel=select(Object.entries(LONG).filter(([k])=>ok.includes(k)||k===current).map(([k,label])=>[k,label+(k===current&&!ok.includes(k)?'（現在の勤務・設定に合いません）':'')]),current);d.append(field('勤務',sel));if(!ok.includes(current))d.append(banner('現在の勤務は、この職員の勤務条件に合いません。勤務を変更してください。'));const fixed=input('checkbox','');fixed.checked=Object.hasOwn(s.locked?.[st.id]||{},day);const lab=el('label',AutoRosterUI.active()?'次の作成でも固定する（両方の方式に適用）':'再作成してもこの勤務を残す','check');lab.prepend(fixed);d.append(lab,el('p','夜勤に変更すると、翌日は明け、翌々日は公休にします。明けに変更すると翌日を公休にします。期間をまたぐ場合は次期の作成時に引き継ぎます。変更後は編集した表の条件を確認します。','muted'),button('変更を反映',async()=>{applyShiftEdit(st,day,sel.value,fixed.checked);delete s.meta;s.workSignature=inputData().signature;save(true);$('dialog').close();await validateCurrent();},'primary wide'));}
async function api(payload,timeoutMs=85000){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),timeoutMs);try{const r=await fetch('/api/schedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:controller.signal});let v;try{v=await r.json();}catch(e){throw Error('計算サービスに接続できませんでした。もう一度お試しください。');}if(!r.ok)throw Error(v.error||'計算を完了できませんでした。');return v;}catch(e){if(e.name==='AbortError')throw Error('通信が時間切れになりました。もう一度お試しください。');throw e;}finally{clearTimeout(timeout);}}
function busy(on){state.busy=on;if(on){clearTimeout(tableCheckTimer);tableCheck=null;state.progressStart=Date.now();timer=setInterval(()=>{if($('elapsed'))$('elapsed').textContent=`${Math.floor((Date.now()-state.progressStart)/1000)}秒 経過`;},1000);}else{clearInterval(timer);for(const e of document.querySelectorAll('button,input,select'))e.disabled=false;}render();}
// 人数不足は表に出して作る。夜勤は毎日1人が必須なので不足扱いにしない。
function staffingShortfall(e){return ['coverage','sunday_limit'].includes(e.code);}
// 中間ルール（守ると作れないときだけ最小限破る）：連勤上限・連勤＋1・日勤の種類（許可した人のみ）。
function ruleException(e,map){if(['consecutive','consecutive_plus_one','no_consecutive_rest','night_remainder'].includes(e.code))return true;return e.code==='day_shift_eligibility'&&!!data.staff.find(s=>s.id===map[e.staff])?.dayShiftFlexible;}
function errorsText(errors,map){const labels={fairness:'余分な公休の偏り',coverage:'必要人数の不足',night_coverage:'夜勤人数',sunday_limit:'日曜の人数緩和の日数超過',request:'希望休への出勤',shift_request:'希望勤務と異なる勤務',locked:'固定した勤務の変更',days_off:'公休不足',rest_blocks:'連休の必須回数の不足',consecutive:'連勤上限',consecutive_plus_one:'連勤＋1の回数',night_link:'夜勤と明けのつながり',night_rest:'明けの翌日は公休',night_eligibility:'夜勤できない日の勤務',day_shift_eligibility:'日勤の種類の違反',eligibility:'勤務形態',overtime_eligibility:'A残の可否',adjacent_overtime:'連日のA残',overtime_limit:'A残の回数',weekly:'週の出勤上限',structure:'未入力または不明な勤務'};return errors.slice(0,8).map(e=>{const name=data.staff.find(s=>s.id===map[e.staff])?.name;if(e.code==='night_coverage'&&Number.isInteger(e.actual))return `${dateLabel(e.day)} 夜勤：${e.actual}人／必要1人${e.actual===0?'（未配置・1人不足）':'（人数超過）'}`;if(e.code==='coverage'&&Number.isInteger(e.required)&&Number.isInteger(e.actual)){const time={420:'朝7:00',600:'昼10:00',1065:'夕17:45'}[e.time]||'';return `${e.day?dateLabel(e.day):''} ${time}：${e.actual}人／必要${e.required}人（${e.required-e.actual}人不足）`;}if(e.code==='day_shift_eligibility')return [name,e.day?dateLabel(e.day):'',`${DAYTYPE[e.allowed]||'日勤の種類'}の設定ですが、「${LONG[e.actual]||e.actual}」が入っています`].filter(Boolean).join('：');if(e.code==='shift_request')return [name,e.day?dateLabel(e.day):'',`希望は「${LONG[e.requested]||e.requested}」ですが、表は「${LONG[e.actual]||e.actual}」です`].filter(Boolean).join('：');if(e.code==='overtime_limit'&&Number.isInteger(e.limit))return `${name||'職員'}さん：A残が${e.actual}回（今期の上限${e.limit}回）`;if(e.code==='rest_blocks')return `${name||'職員'}さん：連休${e.actual}回／必要${e.required}回（${e.required-e.actual}回不足）`;if(e.code==='sunday_limit'&&Number.isInteger(e.actual))return `日曜の人数緩和が${e.actual}日あります（設定は${e.required}日まで）。`;return [name,e.day?dateLabel(e.day):'',labels[e.code]||e.detail||String(e)].filter(Boolean).join('：');}).join('／')+(errors.length>8?` ほか${errors.length-8}件`:'');}
// 作成操作のときだけ表示位置を移す。編集や自動確認では移動しない。
function showCreationSection(id){const target=$(id);if(!target)return;target.tabIndex=-1;target.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:'instant'});}
async function generate(mode='new',allowShortfall=true){
if(AutoRosterUI.active())return AutoRosterUI.generate();
if(state.loadError||state.busy)return;ensureWorkSnapshot();persistWork();if(!activeStaff().length){state.error='今期に入れる職員を1人以上オンにしてください。';render();return;}
const s=schedule(),payload=clone(inputData()),improve=mode==='improve'||mode===60,initial=improve&&!workChanged()&&(ready()||metadata()?.status==='DRAFT')?toRemote(s.assignments,payload.map):undefined,generation=state.generation=(state.generation||0)+1;
const previous=hasTable();
const current=()=>state.generation===generation&&schedule()===s&&inputData().signature===payload.signature;
clearTimeout(tableCheckTimer);tableCheck=null;state.error=null;state.failure=null;state.creationFailure=null;state.progressStage=null;notify('');busy(true);showCreationSection('creation-panel');
try{
let first=null;
const run=await CreationWorkflow.run({input:payload.p,initialAssignments:initial,
request:opts=>api({...opts,allowStaffingShortfall:allowShortfall,allowNightShortfall:false,allowRuleExceptions:allowShortfall}),
nextSeed:()=>state.draftSeed=(state.draftSeed||0)%1000+1,isCurrent:current,
onExtend:r=>{first??=r;state.progressStage=progressText(first,r);render();}});
if(run.stale||!current())return;
const r=run.best||run.last;
if(run.best){RosterStorage.clearResult(s);s.assignments=fromRemote(r.assignments,payload.map);const {assignments,carryForward,...meta}=r;s.workSignature=payload.signature;s.meta={...meta,seconds:run.seconds,timing:{...r.timing,mode:'complete',maxSeconds:CreationWorkflow.MAX_SECONDS},workflow:{rounds:run.rounds,automaticExtended:run.rounds.length>1,done:run.done},signature:payload.signature,tableSignature:JSON.stringify(s.assignments)};if(run.error)state.error='追加計算を完了できなかったため、確認済みの表を表示しています。';}
else if(previous&&(run.error||r?.status==='UNKNOWN')){state.error='計算を完了できなかったため、元の表を保持しました。';}
else if(run.error)state.error=run.error.message;
else if(r?.status==='INFEASIBLE'){const why=diagnosisIssues(r.diagnosis,payload.map)||solverIssues(r.conflictGroups||[],payload.map);state.failure={title:'この条件では表を作れません',notes:['希望・固定・職員の設定が同時には成り立ちません。',why.lead],items:why.items,signature:payload.signature};}
else if(r?.status==='UNKNOWN'){s.retryLong=payload.signature;state.error='時間内に表の成立を確認できませんでした。不可能と判定したわけではありません。';}
else state.error=(r?.errors||[]).map(e=>typeof e==='string'?e:'入力を確認してください').join('／')||'今回の条件で表を作成できませんでした。';
}catch(e){if(current())state.error=e.message;}finally{if(state.generation===generation){state.progressStage=null;busy(false);showCreationSection(state.error?'notice':hasTable()?'roster-result':'creation-panel');}}
}

// 条件と表の両方を照合し、変更中に戻った古い確認結果は採用しない。
function tableCheckIdentity(){return key()+inputData().signature+JSON.stringify(schedule().assignments);}

